n-items:center;gap:10px}.btn{display:inline-block;padding:9px 12px;border:1px solid #d0d5dd;border-radius:9px;background:#fff;color:#172033;font-weight:800;font-size:12px}.btn.primary{background:#155eef;color:#fff;border-color:#155eef}.btn.green{background:#0f766e;color:#fff;border-color:#0f766e}.transport{border:1px solid #e5e7eb;border-radius:14px;padding:15px;display:flex;justify-content:space-between;gap:15px;align-items:center}.transport strong{display:block;font-size:16px}.muted{color:#667085;font-size:12px}.buslist{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin-top:12px}.bus{border:1px solid #e5e7eb;border-radius:12px;padding:12px}.bus strong{display:block}.empty{border:1px dashed #cfd6df;border-radius:13px;padding:24px;text-align:center}.note,.schedule{width:100%;min-height:110px;padding:11px;border:1px solid #d0d5dd;border-radius:10px;font:inherit;resize:vertical}.schedule{min-height:150px}.save{margin-top:8px}.list{display:grid;gap:8px}.person{display:flex;justify-content:space-between;gap:10px;padding:9px 0;border-bottom:1px solid #eef0f2}.person:last-child{border-bottom:0}.pill{background:#f2f4f7;padding:4px 7px;border-radius:99px;font-size:10px;font-weight:800;white-space:nowrap}.links{display:flex;gap:7px;flex-wrap:wrap}.alert{padding:11px;border-radius:10px;margin-bottom:15px}.ok{background:#ecfdf3;color:#067647}.err{background:#fef3f2;color:#b42318}@media(max-width:1050px){.stats{grid-template-columns:repeat(3,1fr)}.layout{grid-template-columns:1fr}}@media(max-width:700px){.side{position:static;width:100%;height:auto}.app{display:block}.main{margin-left:0;width:100%;padding:16px 12px}.stats{grid-template-columns:1fr 1fr}.buslist{grid-template-columns:1fr}.hero{min-height:200px;flex-direction:column;align-items:flex-start}}@media(max-width:450px){.stats{grid-template-columns:1fr}}
</style></head><body><div class="app"><aside class="side"><div class="brand">GoTM</div><div class="org"><strong><?=saas_h($org['name'])?></strong><small><?=saas_h($user['name']??$user['username']??'Account')?></small></div><nav class="nav"><a class="active" href="dashboard.php">▦ Tour dashboard</a><a href="tours.php">← All tours</a></nav><nav class="nav bottom"><a href="tours.php">Tours</a><a href="tour_edit.php?id=<?=$tourId?>">Edit tour</a><a href="public_urls.php">Public URLs</a><a href="billing.php">Billing</a><a href="team.php">Organization team</a><a href="account_settings.php">Account settings</a><a href="logout.php">Log out</a></nav></aside>
<main class="main"><?php if($ok):?><div class="alert ok"><?=saas_h($ok)?></div><?php endif;?><?php if($error):?><div class="alert err"><?=saas_h($error)?></div><?php endif;?>
<section class="hero" <?= $banner!==''?'style="background-image:linear-gradient(90deg,#0009,#0003),url(''.saas_h($banner).'')"' : ''?>><div class="hero-left"><div class="orgname"><?=saas_h($org['name'])?></div><strong><?=saas_h($user['name']??$user['username']??'')?></strong></div><div class="hero-center"><h1><?=saas_h($tour['name'])?></h1><div class="date"><?=saas_h($tour['start_date']??'Date not set')?><?=!empty($tour['end_date'])?' — '.saas_h($tour['end_date']):''?></div></div><div class="hero-actions"><a href="tours.php">All tours</a><a target="_blank" rel="noopener" href="<?=saas_h($publicUrl)?>">Public page</a></div></section>
<section class="stats"><div class="stat"><small>Passengers</small><b><?=$stats['passengers']?></b><div class="sub"><a href="passengers.php">View list</a></div></div><div class="stat"><small>Payments received</small><b><?=number_format($stats['paid'],0)?></b><div class="sub">BDT</div></div><div class="stat"><small>Outstanding</small><b><?=number_format($stats['due'],0)?></b><div class="sub">BDT due</div></div><div class="stat"><small>Expenses</small><b><?=number_format($stats['expenses'],0)?></b><div class="sub">BDT spent</div></div><div class="stat"><small>Net cash</small><b><?=number_format($stats['paid']-$stats['expenses'],0)?></b><div class="sub">received − expenses</div></div></section>
<div class="layout"><div>
<section class="panel"><div class="head"><div><h2>Transport</h2><div class="muted">Default transport: <?=saas_h($transport)?></div></div><a class="btn primary" href="buses.php">＋ Add transport</a></div><?php if($transport==='BUS'):if(!$buses):?><div class="empty" style="margin-top:12px"><h3>Set up your bus</h3><p class="muted">Your tour uses bus transport. Create the bus first, then open its visual seat plan.</p><a class="btn green" href="buses.php">Create bus & seats</a></div><?php else:?><div class="buslist"><?php foreach($buses as $b):?><div class="bus"><strong><?=saas_h($b['name'])?></strong><div class="muted"><?=saas_h($b['layout_type'])?> · <?=$b['seat_count']?> seats</div><div class="links" style="margin-top:9px"><a class="btn" href="seat_plan.php?bus_id=<?=$b['id']?>">Visual seat plan</a><a class="btn" href="bus_edit.php?id=<?=$b['id']?>">Edit</a></div></div><?php endforeach;?></div><?php endif;else:?><div class="transport" style="margin-top:12px"><div><strong><?=saas_h($transport==='NONE'?'No default transport':$transport)?></strong><span class="muted">Add or configure transport when ready.</span></div><a class="btn" href="buses.php">Manage transport</a></div><?php endif;?></section>
<section class="panel"><div class="head"><h2>Quick operations</h2></div><div class="links"><a class="btn primary" href="passengers.php">Passengers</a><a class="btn" href="payments.php">Payments</a><a class="btn" href="expenses.php">Expenses</a><a class="btn" href="rooms.php">Accommodation / rooms</a><a class="btn" href="tour_team.php">Tour team</a><a class="btn" href="features.php">Tour options</a><a class="btn" href="booking_link.php">Booking tools</a></div></section>
<section class="panel"><div class="head"><div><h2>Recent passengers</h2><div class="muted">Latest registrations for this tour</div></div><a class="btn" href="passengers.php">View all</a></div><div class="list"><?php foreach($recentPassengers as $p):$due=max(0,(float)$p['fee']-(float)$p['discount']-(float)$p['paid']);?><div class="person"><div><strong><?=saas_h($p['full_name'])?></strong><div class="muted"><?=saas_h($p['phone']??'')?></div></div><span class="pill"><?=number_format($due,0)?> due</span></div><?php endforeach;if(!$recentPassengers):?><div class="empty">No passengers registered yet.</div><?php endif;?></div></section>
</div><aside>
<section class="panel"><div class="head"><h2>Tour note</h2></div><form method="post"><input type="hidden" name="csrf" value="<?=saas_h(saas_csrf())?>"><input type="hidden" name="action" value="save_note"><textarea class="note" name="notes" placeholder="Important notes for this tour..."><?=saas_h($notes)?></textarea><button class="btn primary save">Save note</button></form></section>
<section class="panel"><div class="head"><h2>Schedule</h2></div><form method="post"><input type="hidden" name="csrf" value="<?=saas_h(saas_csrf())?>"><input type="hidden" name="action" value="save_schedule"><textarea class="schedule" name="schedule" placeholder="09:00 — Departure\n12:30 — Lunch\n15:00 — Hotel check-in"><?=saas_h($schedule)?></textarea><button class="btn primary save">Save schedule</button></form></section>
<section class="panel"><div class="head"><div><h2>Accommodation</h2><div class="muted"><?=$stats['rooms']?> room(s) configured</div></div><a class="btn" href="rooms.php">＋ Add</a></div><p class="muted">Create rooms and assign passengers from the accommodation page.</p><a class="btn primary" href="rooms.php">Manage rooms & assignments</a></section>
<section class="panel"><h2>Public booking</h2><p class="muted">Share the public tour page with customers for registration and updates.</p><div class="links"><a class="btn primary" target="_blank" rel="noopener" href="<?=saas_h($publicUrl)?>">View public page</a><a class="btn" href="tour_settings.php">Public URL & branding</a></div></section>
</aside></div></main></div></body></html>